@@ -0,0 +1,93 @@
+.Root {
+  width: 14rem;
+}
+
+.Control {
+  box-sizing: border-box;
+  display: flex;
+  align-items: center;
+  padding-block: 0.625rem;
+  touch-action: none;
+  -webkit-user-select: none;
+  user-select: none;
+}
+
+.Track {
+  width: 100%;
+  height: 0.25rem;
+  background-color: oklch(92.2% 0 0deg);
+  -webkit-user-select: none;
+  user-select: none;
+
+  @media (prefers-color-scheme: dark) {
+    background-color: oklch(26.9% 0 0deg);
+  }
+}
+
+.Indicator {
+  background-color: oklch(14.5% 0 0deg);
+  -webkit-user-select: none;
+  user-select: none;
+
+  @media (prefers-color-scheme: dark) {
+    background-color: white;
+  }
+}
+
+.Thumb {
+  box-sizing: border-box;
+  width: 1rem;
+  height: 1rem;
+  border: 1px solid oklch(14.5% 0 0deg);
+  background-color: white;
+  -webkit-user-select: none;
+  user-select: none;
+
+  @media (prefers-color-scheme: dark) {
+    border: 1px solid white;
+    background-color: oklch(14.5% 0 0deg);
+  }
+
+  &:has(:focus-visible) {
+    outline: 2px solid oklch(14.5% 0 0deg);
+    outline-offset: 2px;
+
+    @media (prefers-color-scheme: dark) {
+      outline-color: white;
+    }
+  }
+}
+
+.Mark {
+  position: absolute;
+  top: 50%;
+  width: 1px;
+  height: 0.5rem;
+  background-color: oklch(14.5% 0 0deg);
+  transform: translate(-50%, -50%);
+
+  @media (prefers-color-scheme: dark) {
+    background-color: white;
+  }
+}
+
+.MarkLabels {
+  position: relative;
+  height: 1rem;
+  -webkit-user-select: none;
+  user-select: none;
+}
+
+.MarkLabel {
+  position: absolute;
+  top: 0;
+  font-size: 0.75rem;
+  line-height: 1rem;
+  color: oklch(43.9% 0 0deg);
+  white-space: nowrap;
+  transform: translateX(-50%);
+
+  @media (prefers-color-scheme: dark) {
+    color: oklch(70.8% 0 0deg);
+  }
+}

